class _V26Library extends StatefulWidget{const _V26Library();@override State<_V26Library> createState()=>_V26LibraryState();}
class _V26LibraryState extends State<_V26Library>{
 final game=TextEditingController(),note=TextEditingController();List<String> items=[];bool ready=false;
 @override void initState(){super.initState();load();}
 @override void dispose(){game.dispose();note.dispose();super.dispose();}
 Future<void> load()async{final p=await SharedPreferences.getInstance();if(mounted)setState((){items=p.getStringList('v26_games')??[];ready=true;});}
 Future<void> add()async{if(game.text.trim().isEmpty)return;final v=game.text.trim()+' — '+note.text.trim();final p=await SharedPreferences.getInstance();setState(()=>items.insert(0,v));await p.setStringList('v26_games',items);game.clear();note.clear();}
 @override Widget build(BuildContext context)=>ListView(padding:const EdgeInsets.all(12),children:[const Text('مكتبتي وألعاب أتابعها',style:TextStyle(fontSize:20,fontWeight:FontWeight.w900)),TextField(controller:game,decoration:const InputDecoration(labelText:'اسم اللعبة')),TextField(controller:note,decoration:const InputDecoration(labelText:'ملاحظة أو موعد إصدار')),FilledButton(onPressed:add,child:const Text('إضافة للمكتبة')),if(!ready)const LinearProgressIndicator(),if(items.isEmpty)const Text('أضف ألعابك وقائمة الألعاب التي تنتظرها.'),...items.map((x)=>Card(child:ListTile(title:Text(x),trailing:IconButton(icon:const Icon(Icons.delete_outline),onPressed:()async{final p=await SharedPreferences.getInstance();setState(()=>items.remove(x));await p.setStringList('v26_games',items);}))))]);
}
